---RefreshBoard
function CommonTipsBattlePass:RefreshBoardByContent(t)
    t = checkTable(t)

    self._allWeight = 0
    local _t = {}
    for k, v in pairs(t) do 
        for _, vo in ipairs(GoodsUtils.GetGoodsGroupVosById(v.goodsId)) do
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.reward)
            table.insert(_t, {
                name = goodsVo.name, 
                num = checkNumber(vo.minNum),
                weight = checkNumber(vo.weight),
            })

            self._allWeight = self._allWeight + checkNumber(vo.weight)
        end
    end

    for k, v in pairs(_t) do
        local go = self.ListGroup.transform:Find("go"..k)
        if not go then
            go = CfUtils.InstantiateGo(self.Item1, self.ListGroup)
            go.name = "go"..k
        end
        CfUtils.SetActive(go, true)
        local Gradient2 = go.transform:Find("ImgBg").transform:GetComponent(typeof(Gradient2))
        Gradient2.enabled = ((k % 2) == 0)
        CfUtils.FillText(go.transform:Find("Text1"), v.name.."*"..v.num)

        local num = checkNumber(v.weight) / self._allWeight * 100
        CfUtils.FillText(go.transform:Find("Text2"), checkInt(num).."%")
    end
end

